+{
+  "id": "composer",
+  "name": "Conversation Composer",
+  "description": "Renders the canonical Agent UI conversation composer with composable action Slots.",
+  "version": "0.0.1",
+  "capabilities": [
+    "conversation-composer"
+  ],
+  "authoring": {
+    "intents": [
+      "show the primary conversation composer",
+      "compose conversation input actions"
+    ],
+    "visualRole": "conversation composer",
+    "defaultPlacement": {
+      "type": "plugin_slot",
+      "parentPluginId": "conversation-surface",
+      "slot": "composer"
+    }
+  },
+  "slots": {
+    "children": {
+      "triggers": {
+        "description": "Optional conversation input triggers.",
+        "cardinality": "many",
+        "optional": true,
+        "accepts": {
+          "anyOfCapabilities": [
+            "conversation-composer-trigger"
+          ]
+        }
+      },
+      "beforeInput": {
+        "description": "Content displayed between attachments and the composer input.",
+        "cardinality": "many",
+        "optional": true,
+        "accepts": {
+          "anyOfCapabilities": [
+            "conversation-composer-before-input"
+          ]
+        }
+      },
+      "leadingActions": {
+        "description": "Inline actions displayed on the leading side of the composer.",
+        "cardinality": "many",
+        "optional": true,
+        "accepts": {
+          "anyOfCapabilities": [
+            "conversation-composer-leading-action"
+          ]
+        }
+      },
+      "trailingActions": {
+        "description": "Inline actions displayed before the composer submit action.",
+        "cardinality": "many",
+        "optional": true,
+        "accepts": {
+          "anyOfCapabilities": [
+            "conversation-composer-trailing-action"
+          ]
+        }
+      },
+      "submitAction": {
+        "description": "The primary send or stop action for the composer.",
+        "cardinality": "one",
+        "optional": true,
+        "accepts": {
+          "anyOfCapabilities": [
+            "conversation-composer-submit-action"
+          ]
+        }
+      },
+      "input": {
+        "description": "Optional text input presentation; falls back to the canonical textarea.",
+        "cardinality": "one",
+        "optional": true,
+        "accepts": {
+          "anyOfCapabilities": [
+            "conversation-composer-input"
+          ]
+        }
+      }
+    }
+  }
